    status: { ...type.caption, textTransform: "capitalize" },
    toolDetail: { borderTopWidth: 1, borderTopColor: colors.border, padding: spacing.md, gap: spacing.sm },
    mono: { ...type.caption, ...type.mono, color: colors.textMuted },
