        if (part?.functionCall) signals.push({ type: "tool-call", call: { id: String(part.functionCall.id ?? `google-call-${generatedCall++}`), name: String(part.functionCall.name ?? "unknown"), arguments: parsedToolArguments(part.functionCall.args) } });
