import {
	createAssistantMessageEventStream,
	type Api,
	type AssistantMessage,
	type Context,
	type Model,
	type SimpleStreamOptions,
} from "@earendil-works/pi-ai";
import { streamSimple } from "@earendil-works/pi-ai/compat";
import { normalizeToolCallStream } from "../keating/tool-call-normalizer";
import { streamWithApiRetry } from "../keating/api-retry";
import { chatProxyBaseUrl, proxyTargetHeader, shouldProxyModel } from "../lib/provider-proxy";
import {
	isNotOrganicProvider,
	NOTORGANIC_DEFAULT_MODEL,
} from "../notorganic-provider";
import {
	applyGoogleSearchGrounding,
	applyProviderWebSearch,
	resolveProviderWebSearchRoute,
} from "../keating/provider-web-search";
import { signalHostedSearchActivation } from "../keating/search";

// Compatibility exports for existing integrations and tests. New routing should
// prefer applyProviderWebSearch so capability negotiation stays centralized.
export { applyGoogleSearchGrounding, applyProviderWebSearch };
import { getProviderApiKey } from "../lib/provider-models";
import { localModel, DEFAULT_BROWSER_MODEL_ID } from "../stores/local-model";

export const DEFAULT_MODEL = NOTORGANIC_DEFAULT_MODEL;

export function withProviderWebSearch(
	options: SimpleStreamOptions | undefined,
	model: Model<Api>,
	hasApiKey: boolean,
): SimpleStreamOptions | undefined {
	if (model.provider !== "google" && model.provider !== "openai" && model.provider !== "anthropic") {
		return options;
	}
	let signalled = false;

	return {
		...options,
		onPayload: async (payload, payloadModel) => {
			const userPayload = await options?.onPayload?.(payload, payloadModel);
			const nextPayload = userPayload ?? payload;
			const groundedPayload = applyProviderWebSearch(nextPayload, payloadModel, hasApiKey);
			if (groundedPayload !== undefined && !signalled) {
				signalled = true;
				signalHostedSearchActivation(resolveProviderWebSearchRoute(payloadModel, hasApiKey));
			}
			return groundedPayload ?? userPayload;
		},
	};
}

function createBrowserStreamFn() {
	return async (model: Model<Api>, context: Context, options?: SimpleStreamOptions) => {
		const stream = createAssistantMessageEventStream();
		const abortSignal = options?.signal;
		// Report the model that was actually selected, not the catalog default.
		const modelId = model.id || DEFAULT_BROWSER_MODEL_ID;

		const defaultFields = {
			api: "browser" as const,
			provider: "browser" as const,
			model: modelId,
			usage: {
				input: 0,
				output: 0,
				cacheRead: 0,
				cacheWrite: 0,
				totalTokens: 0,
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
			},
		};

		(async () => {
			try {
				if (abortSignal?.aborted) {
					stream.end({
						...defaultFields,
						role: "assistant",
						content: [],
						stopReason: "aborted",
						errorMessage: "Request aborted",
						timestamp: Date.now(),
					} as AssistantMessage);
					return;
				}

				// Selecting a different browser model has to swap the loaded weights
				// before any tokens are generated.
				if (localModel.getState().modelId !== modelId || !localModel.getState().loaded) {
					await localModel.load(modelId);
					const loadState = localModel.getState();
					if (!loadState.loaded) {
						throw new Error(loadState.error ?? `Could not load ${modelId}`);
					}
				}

				const userMessages = context.messages
					.filter((m): m is Extract<typeof m, { role: "user" }> => m.role === "user")
					.map((m) => {
						const content = m.content;
						if (typeof content === "string") return content;
						return content
							.filter((c): c is Extract<typeof c, { type: "text" }> => c.type === "text")
							.map((c) => c.text)
							.join("\n");
					});

				const systemPrompt = context.systemPrompt || "";
				const conversationHistory = userMessages.join("\n\n");
				const fullPrompt = systemPrompt
					? `${systemPrompt}\n\n${conversationHistory}`
					: conversationHistory;

				const partialMessage: AssistantMessage = {
					...defaultFields,
					role: "assistant",
					content: [{ type: "text", text: "" }],
					stopReason: "stop",
					timestamp: Date.now(),
				};

				stream.push({ type: "start", partial: partialMessage });
				stream.push({ type: "text_start", contentIndex: 0, partial: partialMessage });

				const response = await localModel.generate(
					fullPrompt,
					{ max_length: options?.maxTokens ?? 1024, temperature: options?.temperature ?? 0.7 },
					(token: string) => {
						const textBlock = partialMessage.content[0];
						if (textBlock.type === "text") textBlock.text += token;
						stream.push({ type: "text_delta", contentIndex: 0, delta: token, partial: partialMessage });
					},
				);

				if (abortSignal?.aborted) {
					stream.end({
						...defaultFields,
						role: "assistant",
						content: [{ type: "text", text: response }],
						stopReason: "aborted",
						errorMessage: "Request aborted",
						timestamp: Date.now(),
					} as AssistantMessage);
					return;
				}

				stream.push({
					type: "text_end",
					contentIndex: 0,
					content: response,
					partial: partialMessage,
				});
				stream.end({
					...defaultFields,
					role: "assistant",
					content: [{ type: "text", text: response }],
					stopReason: "stop",
					timestamp: Date.now(),
				} as AssistantMessage);
			} catch (error) {
				const message = error instanceof Error ? error.message : String(error);
				// Without this the failure is invisible: the UI shows the generic
				// "Request failed" card and nothing reaches the console.
				console.error(`[keating-stream] browser model ${modelId} failed:`, error);
				stream.end({
					...defaultFields,
					role: "assistant",
					content: [],
					stopReason: "error",
					errorMessage: message,
					timestamp: Date.now(),
				} as AssistantMessage);
			}
		})();

		return stream;
	};
}

export async function hybridStreamFn(model: Model<Api>, context: Context, options?: SimpleStreamOptions) {
	if (model.provider === "browser") {
		return normalizeToolCallStream(await createBrowserStreamFn()(model, context, options), context);
	}

	const apiKey = options?.apiKey ?? await getProviderApiKey(model.provider);
	let streamOptions: SimpleStreamOptions | undefined = apiKey ? { ...options, apiKey } : options;
	if (isNotOrganicProvider(model.provider)) {
		streamOptions = {
			...streamOptions,
			headers: {
				...streamOptions?.headers,
				"idempotency-key": `keating_${crypto.randomUUID()}`,
			},
		};
	}

	if (shouldProxyModel(model)) {
		const proxiedModel = {
			...model,
			baseUrl: chatProxyBaseUrl(),
		};
		const proxiedOptions: SimpleStreamOptions = {
			...streamOptions,
			headers: {
				...streamOptions?.headers,
				"x-target-url": proxyTargetHeader(model.baseUrl),
			},
		};
		if (import.meta.env.DEV) {
			const hasApiKey = !!proxiedOptions.apiKey;
			console.log(`[keating:stream] proxy ${model.provider} -> ${model.baseUrl} (apiKey=${hasApiKey})`);
		}
		const mergedOptions = withProviderWebSearch(proxiedOptions, proxiedModel, !!apiKey);
		return normalizeToolCallStream(
			streamWithApiRetry(proxiedModel, context, mergedOptions, (nextOptions) => streamSimple(proxiedModel, context, nextOptions)),
			context,
		);
	}

	const mergedOptions = withProviderWebSearch(streamOptions, model, !!apiKey);
	return normalizeToolCallStream(
		streamWithApiRetry(model, context, mergedOptions, (nextOptions) => streamSimple(model, context, nextOptions)),
		context,
	);
}
}

function contentFromAppendMessage(message: AppendMessage): PromptContent[] {
  const content: PromptContent[] = [];
  for (const part of message.content) {
    if (part.type === "text" && part.text.trim()) {
      content.push({ type: "text", text: part.text });
    } else if (part.type === "image") {
      const image = dataUrlToImageContent(part.image);
      if (image) content.push(image);
    } else if (part.type === "file") {
      content.push({
        type: "text",
        text: `[file: ${part.filename ?? "attachment"}]\n${part.data}`,
      });
    }
  }

  for (const attachment of message.attachments ?? []) {
    for (const part of attachment.content ?? []) {
      if (part.type === "text" && part.text.trim()) {
        content.push({ type: "text", text: part.text });
      } else if (part.type === "image") {
        const image = dataUrlToImageContent(part.image);
        if (image) content.push(image);
      } else if (part.type === "file") {
        content.push({
          type: "text",
          text: `[file: ${part.filename ?? attachment.name}]\n${part.data}`,
        });
      }
    }
  }

  return content;
}

function assistantContentFromAgentContent(content: unknown) {
  if (typeof content === "string")
    return [{ type: "text" as const, text: content }];
  if (!Array.isArray(content)) return [{ type: "text" as const, text: "" }];
  return content
    .map((part: any) => {
      if (part?.type === "text") {
        return {
          type: "text" as const,
          text: displayTextFromAgentText(part.text ?? ""),
        };
      }
      if (part?.type === "image") {
        return {
          type: "image" as const,
          image: `data:${part.mimeType};base64,${part.data}`,
          filename: part.filename,
        };
      }
      return { type: "text" as const, text: textFromContent([part]) };
    })
    .filter((part) => part.type !== "text" || part.text);
}

function textFromContent(content: unknown): string {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .map((part) => {
      if (part?.type === "text" && typeof part.text === "string")
        return part.text;
      if (part?.type === "thinking" && typeof part.thinking === "string")
        return part.thinking;
      if (part?.type === "reasoning" && typeof part.text === "string")
        return part.text;
      if (part?.type === "image") return "[image]";
      if (part?.type === "toolCall") return `[tool: ${part.name ?? "unknown"}]`;
      return "";
    })
    .filter(Boolean)
    .join("\n");
}

function foldToolResults(messages: AgentMessage[]): AgentMessage[] {
  const folded: AgentMessage[] = [];
  const assistantByToolCallId = new Map<string, any>();

  for (const message of messages) {
    const msg = message as any;
    if (msg.role === "assistant" && Array.isArray(msg.content)) {
      const clone = {
        ...msg,
        content: msg.content.map((part: any) => ({ ...part })),
      };
      for (const part of clone.content) {
        if (part?.type === "toolCall" && part.id) {
          assistantByToolCallId.set(part.id, part);
        }
      }
      folded.push(clone as AgentMessage);
      continue;
    }

    if (msg.role === "toolResult") {
      const toolCall = assistantByToolCallId.get(msg.toolCallId);
      if (toolCall) {
        toolCall.__toolResult = msg.content;
        toolCall.__toolDetails = msg.details;
        toolCall.__toolError = msg.isError;
        continue;
      }
    }

    folded.push(message);
  }

  return folded;
}

function filterSpeechMessages(
  messages: AgentMessage[],
  speechEnabled: boolean,
): AgentMessage[] {
  if (speechEnabled) return messages;
  return messages
    .map((message) => {
      const msg = message as any;
      if (msg.role === "toolResult" && msg.toolName === KEATING_VOICE_TOOL_NAME)
        return null;
      if (msg.role !== "assistant" || !Array.isArray(msg.content))
        return message;

      const content = msg.content.filter(
        (part: any) =>
          !(part?.type === "toolCall" && part.name === KEATING_VOICE_TOOL_NAME),
      );
      if (content.length === msg.content.length) return message;
      return { ...msg, content } as AgentMessage;
    })
    .filter((message): message is AgentMessage => message !== null);
}

function mergeConsecutiveAssistantMessages(
  messages: AgentMessage[],
): AgentMessage[] {
  const merged: AgentMessage[] = [];
  for (const message of messages) {
    const msg = message as any;
    if (msg.role === "assistant" && merged.length > 0) {
      const last = merged[merged.length - 1] as any;
      if (last.role === "assistant") {
        const left = Array.isArray(last.content)
          ? last.content.map((p: any) => ({ ...p }))
          : [{ type: "text", text: textFromContent(last.content) }];
        const right = Array.isArray(msg.content)
          ? msg.content.map((p: any) => ({ ...p }))
          : [{ type: "text", text: textFromContent(msg.content) }];
        last.content = [...left, ...right];
        if (msg.timestamp) last.timestamp = msg.timestamp;
        if (msg.stopReason !== undefined) last.stopReason = msg.stopReason;
        if (msg.errorMessage) {
          last.errorMessage = msg.errorMessage;
          last.stopReason = msg.stopReason ?? last.stopReason;
        }
        if (msg.__keatingStreaming)
          last.__keatingStreaming = msg.__keatingStreaming;
        continue;
      }
    }
    merged.push(message);
  }
  return merged;
}

function hasRenderableAssistantContent(content: unknown): boolean {
  if (!Array.isArray(content))
    return typeof content === "string" && content.trim().length > 0;
  return content.some((part: any) => {
    if (part?.type === "text")
      return typeof part.text === "string" && part.text.trim().length > 0;
    if (part?.type === "thinking")
      return (
        typeof part.thinking === "string" && part.thinking.trim().length > 0
      );
    if (part?.type === "reasoning")
      return typeof part.text === "string" && part.text.trim().length > 0;
    if (part?.type === "toolCall") return true;
    if (part?.type === "image") return true;
    return false;
  });
}

function isSameStreamingAssistantMessage(
  message: unknown,
  streamingMessage: unknown,
): boolean {
  const left = message as any;
  const right = streamingMessage as any;
  if (!left || !right) return false;
  if (left === right) return true;
  if (left.role !== "assistant" || right.role !== "assistant") return false;
  if (left.timestamp !== right.timestamp) return false;
  return (
    JSON.stringify(left.content ?? null) ===
    JSON.stringify(right.content ?? null)
  );
}

function visibleAgentMessages(
  agent: Agent | null,
  speechEnabled: boolean,
): AgentMessage[] {
  if (!agent) return [];
  const messages = [...agent.state.messages];
  const streamingMessage = agent.state.streamingMessage as any;
  if (
    streamingMessage?.role === "assistant" &&
    hasRenderableAssistantContent(streamingMessage.content)
  ) {
    const alreadyVisible = messages.some((message) =>
      isSameStreamingAssistantMessage(message, streamingMessage),
    );
    if (!alreadyVisible) {
      messages.push({
        ...streamingMessage,
        __keatingStreaming: true,
        content: Array.isArray(streamingMessage.content)
          ? streamingMessage.content.map((part: any) => ({ ...part }))
          : streamingMessage.content,
      } as AgentMessage);
    }
  }
  return mergeConsecutiveAssistantMessages(
    foldToolResults(filterSpeechMessages(messages, speechEnabled)),
  );
}

type AssistantTextPart =
  | { type: "text"; text: string }
  | { type: "reasoning"; text: string };

const THINK_TAG_PATTERN = /<\/?think(?:ing)?>/gi;

function normalizeReasoningText(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

function normalizeAssistantContentParts(parts: any[]): any[] {
  const normalized: any[] = [];

  for (const part of parts) {
    if (part.type !== "reasoning") {
      normalized.push(part);
      continue;
    }

    const text = part.text ?? "";
    const key = normalizeReasoningText(text);
    if (!key) continue;

    const last = normalized.at(-1);
    if (last?.type === "reasoning") {
      const lastText = last.text ?? "";
      const lastKey = normalizeReasoningText(lastText);
      if (lastKey === key) continue;
      if (lastKey.includes(key)) continue;
      if (key.includes(lastKey)) {
        last.text = text;
        continue;
      }
      last.text = `${lastText.trim()}\n\n${text.trim()}`;
      continue;
    }

    const duplicateIndex = normalized.findIndex((candidate) => {
      if (candidate.type !== "reasoning") return false;
      const candidateKey = normalizeReasoningText(candidate.text ?? "");
      return (
        candidateKey === key ||
        candidateKey.includes(key) ||
        key.includes(candidateKey)
      );
    });
    if (duplicateIndex !== -1) {
      const duplicate = normalized[duplicateIndex];
      const duplicateKey = normalizeReasoningText(duplicate.text ?? "");
      if (key.length > duplicateKey.length) duplicate.text = text;
      continue;
    }

    normalized.push(part);
  }

  return normalized;
}

function assistantTextParts(text: string): AssistantTextPart[] {
  if (!text) return [{ type: "text", text: "" }];

  // Some OpenAI-compatible reasoning models leak malformed closing tags without
  // a matching opening tag. When that happens, the safest behavior is to treat
  // everything before the final closing tag as hidden reasoning and only render
  // the post-close tail as the learner-visible answer.
  if (!/<think(?:ing)?>/i.test(text) && /<\/think(?:ing)?>/i.test(text)) {
    const matches = [...text.matchAll(/<\/think(?:ing)?>/gi)];
    const last = matches.at(-1);
    if (last && typeof last.index === "number") {
      const reasoning = text.slice(0, last.index).trim();
      const visible = text.slice(last.index + last[0].length).trim();
      const parts: AssistantTextPart[] = [];
      if (reasoning) parts.push({ type: "reasoning", text: reasoning });
      if (visible) parts.push({ type: "text", text: visible });
      return parts.length > 0 ? parts : [{ type: "text", text: "" }];
    }
  }

  const parts: AssistantTextPart[] = [];
  let cursor = 0;
  let reasoningStart: number | null = null;

  for (const match of text.matchAll(THINK_TAG_PATTERN)) {
    const tag = match[0].toLowerCase();
    const tagIndex = match.index ?? 0;
    if (!tag.startsWith("</")) {
      if (reasoningStart === null) {
        const visible = text.slice(cursor, tagIndex);
        if (visible) parts.push({ type: "text", text: visible });
        reasoningStart = tagIndex + match[0].length;
        cursor = reasoningStart;
      }
      continue;
    }

    if (reasoningStart !== null) {
      const reasoning = text.slice(reasoningStart, tagIndex);
      if (reasoning.trim()) parts.push({ type: "reasoning", text: reasoning });
      cursor = tagIndex + match[0].length;
      reasoningStart = null;
    }
  }

  if (reasoningStart !== null) {
    const reasoning = text.slice(reasoningStart);
    if (reasoning.trim()) parts.push({ type: "reasoning", text: reasoning });
    return parts.length > 0 ? parts : [{ type: "text", text: "" }];
  }

  const tail = text.slice(cursor);
  if (tail) parts.push({ type: "text", text: tail });
  return parts.length > 0 ? parts : [{ type: "text", text: "" }];
}

function assistantHasPendingToolCalls(content: unknown): boolean {
  if (!Array.isArray(content)) return false;
  return content.some(
    (part: any) =>
      part?.type === "toolCall" &&
      part.__toolResult === undefined &&
      part.__toolDetails === undefined &&
      part.__toolError === undefined,
  );
}

function assistantHasToolCalls(content: unknown): boolean {
  return (
    Array.isArray(content) &&
    content.some((part: any) => part?.type === "toolCall")
  );
}

function toAssistantMessage(
  message: AgentMessage,
  index: number,
  totalMessages: number,
  isRunning: boolean,
  fallbackProvider?: string,
): ThreadMessageLike {
  const msg = message as any;
  const timestamp =
    typeof msg.timestamp === "number" ? new Date(msg.timestamp) : new Date();

  // Only the last assistant message should show "running" status.
  // During tool execution, isRunning is still true, but the assistant message
  // is already complete (followed by toolResult messages).
  const isLastMessage = index === totalMessages - 1;
  const hasStopReason = msg.stopReason != null;
  const isActivelyStreaming =
    isRunning &&
    msg.role === "assistant" &&
    isLastMessage &&
    !(
      assistantHasToolCalls(msg.content) &&
      !assistantHasPendingToolCalls(msg.content)
    ) &&
    (msg.__keatingStreaming === true || !hasStopReason);
  const status = isActivelyStreaming
    ? { type: "running" as const }
    : msg.stopReason === "error"
      ? {
          type: "incomplete" as const,
          reason: "error" as const,
          error: msg.errorMessage ?? "Assistant response failed",
        }
      : msg.stopReason === "aborted"
        ? { type: "incomplete" as const, reason: "cancelled" as const }
        : { type: "complete" as const, reason: "stop" as const };

  if (msg.role === "assistant") {
    const content = normalizeAssistantContentParts(
      Array.isArray(msg.content)
        ? msg.content.flatMap((part: any) => {
            if (part?.type === "thinking")
              return [
                { type: "reasoning" as const, text: part.thinking ?? "" },
              ];
            if (part?.type === "toolCall") {
              return [
                {
                  type: "tool-call" as const,
                  toolCallId: part.id ?? `tool-${index}`,
                  toolName: part.name ?? "tool",
                  args: part.arguments ?? {},
                  argsText: JSON.stringify(part.arguments ?? {}),
                  result: part.__toolResult ?? part.__toolDetails,
                  isError: part.__toolError,
                },
              ];
            }
            return assistantTextParts(part?.text ?? "");
          })
        : assistantTextParts(textFromContent(msg.content)),
    );

    const id = `assistant-${index}-${msg.timestamp ?? ""}`;

    if (status.type === "incomplete" && status.reason === "error") {
      const errorText = msg.errorMessage ?? "Assistant response failed";
      if (!content.some((c: any) => c.type === "text" && c.text)) {
        content.unshift({
          type: "text" as const,
          text: `${ERROR_TEXT_PREFIX}${errorText}`,
        });
      }
    }

    if (
      status.type === "incomplete" &&
      status.reason === "cancelled" &&
      !content.some((c: any) => c.type === "text" && c.text)
    ) {
      content.unshift({
        type: "text" as const,
        text: msg.errorMessage ?? "Response interrupted before it finished.",
      });
    }

    const authError = authErrorFromAgentMessage(msg, fallbackProvider);
    const llmFailure =
      status.type === "incomplete"
        ? classifyLlmError(
            msg.errorMessage ??
              (status.reason === "cancelled"
                ? "Request aborted"
                : "Assistant response failed"),
          )
