   485	        const call = pending.get(key) ?? { id: String(payload.item.call_id ?? payload.item.id ?? `openai-call-${generatedCall++}`), name: String(payload.item.name ?? "unknown"), argumentsText: String(payload.item.arguments ?? "") };
